import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("renaming a vendor to another vendor's name is refused regardless of case", { tag: "@LIF-10" }, async ({ apiAs, factory }) => {
  // Arrange: two draft vendors for the member's tenant, with unique names.
  const atlasName = uniqueName("Atlas Freight");
  const borealisName = uniqueName("Borealis Freight");
  await factory.vendor({ name: atlasName });
  const borealis = await factory.vendor({ name: borealisName });
  const member = await apiAs("member");

  // Act: rename Borealis to Atlas's name in different letter case.
  const response = await member.patch(`/api/vendors/${borealis.id}`, {
    data: { name: atlasName.toUpperCase() },
  });

  // Assert: the rename is refused with the documented error code.
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Assert: the stored name is unchanged, re-read from the API.
  const stored = await expectStatus<{ name: string }>(await member.get(`/api/vendors/${borealis.id}`), 200);
  expect(stored.name).toBe(borealisName);
});
